#!/usr/bin/env python3
"""Generate client price literals from the canonical, unit-labelled Rust policy."""
import re
import sys
from pathlib import Path

root = Path(__file__).resolve().parent.parent
source = (root / 'crates/financial-core/src/price_policy.rs').read_text()
constants = re.findall(r'^pub const ([A-Z_]+): (u16|u64|i32|i64) = (-?[\d_]+);$', source, re.M)
assert constants and len(constants) == len(re.findall(r'^pub const ', source, re.M)), 'Unsupported policy expression'
lines = [
    '// Generated by ops/generate-price-policy.py from financial-core/src/price_policy.rs.',
    '// Do not edit: numeric capacity and deployment policy are distinct contracts.',
]
for name, kind, literal in constants:
    # Version/exponent are metadata; all financial values remain exact BigInts.
    lines.append(f'export const {name} = {literal}{"" if kind in ("u16", "i32") else "n"};')
expected = '\n'.join(lines) + '\n'
target = root / 'packages/sdk/src/price-policy-constants.ts'
if '--check' in sys.argv:
    assert target.read_text() == expected, 'SDK price policy is stale; run python3 ops/generate-price-policy.py'
else:
    target.write_text(expected)
